export function toHatredDayNumber(value){const n=Number(String(value??'').replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))));return Number.isInteger(n)&&n>=1&&n<=28?n:null;}
export function getHatredDailyAssistantPromptGroups(day){const n=toHatredDayNumber(day),g=HATRED_DAILY_ASSISTANT_GUIDES.find(x=>x.day===n);if(!g)return[];return[{label:'فهم تمرین روز '+g.day,questions:g.questions.filter(x=>['exercise_meaning','exercise_example'].includes(x.kind))},{label:'فهم اقدام اختصاصی روز '+g.day,questions:g.questions.filter(x=>['action_meaning','action_example'].includes(x.kind))},{label:'تفاوت تمرین و اقدام',questions:g.questions.filter(x=>x.kind==='exercise_action_difference')},{label:'اجرا و موانع',questions:g.questions.filter(x=>['light_version','not_done','no_event','can_change','duration'].includes(x.kind))},{label:'ارزیابی و ایمنی',questions:g.questions.filter(x=>['hostility_increased','talk_other','success','stop'].includes(x.kind))}];}
const heading=g=>'راهنمای روز '+String(g.day).replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[+d])+' نفرت — '+g.title;
const safety='این راهنما آموزشی است و تشخیص یا درمان نیست. احساس نفرت مجوز تهدید، تحقیر، تعقیب، افشا، تبعیض یا آسیب نیست؛ تجربه واقعی خشونت، تبعیض یا نقض مرز را نیز انکار نکن. بخشایش، آشتی، تماس یا گفت‌وگوی مستقیم اجباری نیست. در خطر فوری برای تو یا دیگری، تمرین را متوقف کن، فاصله امن ایجاد کن و از فرد قابل اعتماد یا خدمات اضطراری محل زندگی کمک بگیر. اگر تجربه خودبیزاری است، این بسته را ادامه نده و مسیر T18 را انتخاب کن.';
export function answerHatredDailyPreparedQuestion({day,message,dailyContent}={}){const n=toHatredDayNumber(day),g=HATRED_DAILY_ASSISTANT_GUIDES.find(x=>x.day===n);if(!g)return null;const q=g.questions.find(x=>x.value===String(message||'').trim());if(!q)return null;const e=String(dailyContent?.exercise||g.exercise||'').trim(),a=String(dailyContent?.actionText||dailyContent?.action||g.action||'').trim(),h=heading(g),s=safety;switch(q.kind){case'exercise_meaning':return h+'\n\n**منظور از تمرین امروز چیست؟**\n'+e+'\n\n**هدف:** '+g.objective+'\n\n**مهارت:** '+g.skill+'\n\n**معیار:** '+g.successCriterion+'\n\nتماس یا مواجهه با فرد موردنظر لازم نیست.\n\n'+s;case'exercise_example':return h+'\n\n**مثال فرضی تمرین امروز**\n'+g.exerciseExample+'\n\n**ارتباط با تمرین:** '+e+'\n\nمثال فرضی است و تجربه تو را فرض نمی‌کند؛ جزئیات شناسایی‌کننده را ثبت نکن.\n\n'+s;case'action_meaning':return h+'\n\n**اقدام اختصاصی امروز**\n'+a+'\n\n**منطق:** '+g.mechanism+'\n\nاقدام اختیاری است؛ اگر ناامن است، فاصله یا عدم اقدام معتبر است.\n\n'+s;case'action_example':return h+'\n\n**مثال فرضی اقدام امروز**\n'+g.actionExample+'\n\n**اقدام امروز:** '+a+'\n\nتماس، آشتی یا افشای اطلاعات اجباری نیست.\n\n'+s;case'light_version':return h+'\n\n**نسخه سبک**\n'+g.lightVersion+'\n\nاگر همین مقدار هم فشار ایجاد می‌کند، مکث یا توقف معتبر است.\n\n'+s;case'success':return h+'\n\n**معیار موفقیت**\n'+g.successCriterion+'\n\nاین معیار توصیفی است، نه نمره روان‌سنجی یا اثبات کاهش نفرت.\n\n'+s;case'stop':return h+'\n\n**شرط توقف**\n'+g.stopCondition+'\n\nدر خطر واقعی، تمرین را جایگزین حفاظت یا کمک انسانی نکن.\n\n'+s;case'no_event':return h+'\n\n**اگر امروز نمونه‌ای نبود**\nموقعیت تعارض یا تماس را عمداً ایجاد نکن. می‌توانی نمونه گذشته کم‌فشار را بدون جزئیات حساس مرور کنی، نسخه سبک را انجام بدهی یا مکث کنی.\n\n**نسخه سبک:** '+g.lightVersion;case'exercise_action_difference':return h+'\n\n**تفاوت تمرین و اقدام**\n**تمرین:** '+e+'\n\n**اقدام:** '+a+'\n\nتمرین برای مشاهده است؛ اقدام اختیاری و مشروط به ایمنی است.\n\n'+s;case'not_done':return h+'\n\n**اگر انجام ندادی یا فراموش کردی**\nجبران فشرده لازم نیست و خودت را سرزنش نکن. اگر انجام‌ندادن به دلیل ناامنی یا تشدید خصومت بوده، توقف تصمیم مناسبی بوده است.\n\n**نسخه سبک:** '+g.lightVersion;case'hostility_increased':return h+'\n\n**اگر خصومت یا میل به واکنش بیشتر شد**\nتمرین را متوقف کن؛ پیام یا اقدامی نفرست، پیگیری یا مواجهه را ادامه نده و در صورت امکان فاصله امن بگیر. اگر احتمال آسیب فوری به خود یا دیگری وجود دارد، تنها نمان و فوراً از فرد امن یا خدمات اضطراری کمک بگیر.\n\n**شرط توقف روز:** '+g.stopCondition+'\n\n'+s;case'talk_other':return h+'\n\n**آیا باید با فرد دیگری صحبت کنی؟**\nخیر؛ برای انجام تمرین لازم نیست. اگر حمایت می‌خواهی فقط منبع امن و قابل اعتماد را انتخاب کن. جزئیات شناسایی‌کننده را در محیط تحت نظارت افشا نکن. گفت‌وگوی مستقیم، میانجی‌گری و آشتی تکلیف نیست.\n\n'+s;case'can_change':return h+'\n\n**تغییر تمرین**\nمی‌توانی آن را کوتاه کنی، نسخه سبک را انتخاب کنی یا به زمان دیگری موکول کنی؛ اما مرزهای ایمنی را حذف نکن و برای تکمیل تمرین تماس یا مواجهه انجام نده.\n\n**نسخه سبک:** '+g.lightVersion+'\n\n'+s;case'duration':return h+'\n\n**مدت زمان**\nزمان استاندارد معتبر ثبت نشده است؛ عددی حدس نمی‌زنم. فقط به‌اندازه‌ای پیش برو که قابل تحمل و امن باشد؛ توقف زودتر پذیرفته است.\n\n**هدف:** '+g.objective;default:return null;}}
